import duckdb

con = duckdb.connect()
con.execute('''
    CREATE TABLE inventario (sku VARCHAR PRIMARY KEY, stock INT, precio DECIMAL(10,2));
    INSERT INTO inventario VALUES ('A100', 10, 25.00), ('B200', 50, 10.00);

    CREATE TABLE incoming_updates (sku VARCHAR, stock INT, precio DECIMAL(10,2));
    -- A100 cambia de stock, C300 es un producto nuevo
    INSERT INTO incoming_updates VALUES ('A100', 15, 25.00), ('C300', 100, 5.00);

    -- Emulacion de MERGE INTO
    UPDATE inventario 
    SET stock = u.stock 
    FROM incoming_updates u 
    WHERE inventario.sku = u.sku;

    INSERT INTO inventario 
    SELECT u.sku, u.stock, u.precio 
    FROM incoming_updates u 
    LEFT JOIN inventario i ON u.sku = i.sku 
    WHERE i.sku IS NULL;
''')

res = con.execute('SELECT sku, stock, precio FROM inventario ORDER BY sku').fetchall()
for r in res:
    print(f'SKU {r[0]}: Stock={r[1]}, Precio=${r[2]}')
